// Маппинг лида VK → полезная нагрузка для Fitbase.
// Подгони пути к полям под реальный ответ VK (см. один лид в предыдущей ноде).
const out = [];
for (const item of $input.all()) {
  const l = item.json;

  // --- достаём поля лида (поправь пути под свой ответ VK) ---
  const phoneRaw = l.phone ?? l.contact_phone ?? (l.answers && l.answers.phone) ?? '';
  const name     = l.name  ?? l.contact_name  ?? (l.answers && l.answers.name)  ?? '';
  const adPlanId = l.ad_plan_id  ?? l.campaign_id ?? l.plan_id  ?? '';
  const adGroupId= l.ad_group_id ?? l.group_id    ?? '';
  const bannerId = l.banner_id   ?? l.ad_id        ?? '';
  const leadId   = l.id ?? l.lead_id ?? '';

  // нормализуем телефон в 11 цифр (7XXXXXXXXXX)
  let phone = String(phoneRaw).replace(/\D/g, '');
  if (phone.length === 10) phone = '7' + phone;
  if (phone.length === 11 && phone.startsWith('8')) phone = '7' + phone.slice(1);

  out.push({ json: {
    external_lead_id: String(leadId),
    name: String(name).trim(),
    phone,
    utm_source:  'vk_ads',
    utm_medium:  'lead_form',
    utm_campaign: String(adPlanId),   // ← рекламная кампания (ad_plan)
    utm_term:     String(adGroupId),  // ← группа (ad_group)
    utm_content:  String(bannerId),   // ← объявление (banner)
  }});
}
return out;

